<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { PhArrowLeft as ArrowLeft, PhArrowRight as ArrowRight, PhCheck as Check, PhUserPlus as UserPlus } from '@phosphor-icons/vue'
import { borrowers, money } from '../data/demo'
import api from '../services/api'
const step = ref(1)
const form = reactive({ borrower: borrowers[1].id, principal: 500000, rate: 10, duration: 4, frequency: 'weekly', disbursement: '2026-08-26', firstPayment: '2026-09-02', fees: 0 })
const borrowerOptions = ref(borrowers); const branches = ref([]); const saving = ref(false); const error = ref(''); const router = useRouter()
const interest = computed(() => Math.round(form.principal * form.rate / 100))
const total = computed(() => Number(form.principal) + interest.value + Number(form.fees))
const installment = computed(() => Math.ceil(total.value / Math.max(1, form.duration)))
const selected = computed(() => borrowerOptions.value.find((b) => b.id === form.borrower) || borrowerOptions.value[0])
onMounted(async () => { try { const [{ data }, branchResponse] = await Promise.all([api.get('/borrowers'), api.get('/branches')]); borrowerOptions.value = data.data.map((b) => ({ id: b.id, name: b.full_name, phone: b.phone_number })); branches.value = branchResponse.data; form.borrower = borrowerOptions.value[0]?.id } catch { /* Demo preview remains available. */ } })
async function createLoan() { saving.value = true; error.value = ''; try { await api.post('/loans', { borrower_id: form.borrower, branch_id: branches.value[0]?.id, principal_amount: form.principal, interest_rate: form.rate, interest_method: 'simple', interest_period: 'loan_term', duration: form.duration, duration_unit: 'weeks', repayment_frequency: form.frequency, disbursement_date: form.disbursement, first_repayment_date: form.firstPayment, fees_amount: form.fees }); router.push('/loans') } catch (e) { error.value = e.response?.data?.message || 'Could not create this loan.' } finally { saving.value = false } }
</script>
<template><div class="mx-auto max-w-3xl"><div class="mb-6 flex items-center gap-2" aria-label="Loan steps"><div v-for="n in 3" :key="n" class="flex flex-1 items-center gap-2"><span class="grid size-8 shrink-0 place-items-center rounded-full text-sm font-bold" :class="n <= step ? 'bg-emerald-700 text-white' : 'bg-stone-200 text-stone-500'">{{ n < step ? '✓' : n }}</span><span class="hidden text-sm font-semibold sm:block">{{ ['Customer','Loan terms','Review'][n-1] }}</span></div></div><section class="surface p-5 sm:p-7"><p v-if="error" class="mb-5 rounded-xl bg-rose-50 p-3 text-sm text-rose-800">{{ error }}</p><div v-if="step === 1"><h2 class="text-xl font-bold">Choose customer</h2><label class="label mt-6" for="borrower">Borrower</label><select id="borrower" v-model="form.borrower" class="field"><option v-for="person in borrowerOptions" :key="person.id" :value="person.id">{{ person.name }} · {{ person.phone }}</option></select><RouterLink to="/borrowers" class="btn-secondary mt-4"><UserPlus :size="19"/>Add new borrower</RouterLink></div><div v-else-if="step === 2"><h2 class="text-xl font-bold">Loan terms</h2><div class="mt-6 grid gap-5 sm:grid-cols-2"><label><span class="label">Principal amount</span><input v-model.number="form.principal" type="number" class="field"/></label><label><span class="label">Interest rate (%)</span><input v-model.number="form.rate" type="number" step="0.1" class="field"/></label><label><span class="label">Duration</span><input v-model.number="form.duration" type="number" class="field"/></label><label><span class="label">Repayment frequency</span><select v-model="form.frequency" class="field"><option value="daily">Daily</option><option value="weekly">Weekly</option><option value="biweekly">Biweekly</option><option value="monthly">Monthly</option></select></label><label><span class="label">Disbursement date</span><input v-model="form.disbursement" type="date" class="field"/></label><label><span class="label">First repayment</span><input v-model="form.firstPayment" type="date" class="field"/></label></div><div class="mt-6 grid gap-3 rounded-xl bg-emerald-50 p-5 sm:grid-cols-3"><div><p class="text-xs text-emerald-800">Customer receives</p><strong>{{ money(form.principal) }}</strong></div><div><p class="text-xs text-emerald-800">Total repayment</p><strong>{{ money(total) }}</strong></div><div><p class="text-xs text-emerald-800">Installment</p><strong>{{ money(installment) }}</strong></div></div></div><div v-else><h2 class="text-xl font-bold">Review loan</h2><div class="mt-6 divide-y divide-stone-100 rounded-xl border border-stone-200 px-5"><div class="flex justify-between py-4"><span class="text-stone-500">Borrower</span><strong>{{ selected?.name }}</strong></div><div class="flex justify-between py-4"><span class="text-stone-500">Principal</span><strong>{{ money(form.principal) }}</strong></div><div class="flex justify-between py-4"><span class="text-stone-500">Interest</span><strong>{{ money(interest) }}</strong></div><div class="flex justify-between py-4"><span class="text-stone-500">Total repayment</span><strong>{{ money(total) }}</strong></div><div class="flex justify-between py-4"><span class="text-stone-500">Frequency</span><strong class="capitalize">{{ form.frequency }}</strong></div></div></div><div class="mt-8 flex justify-between border-t border-stone-200 pt-5"><button v-if="step > 1" class="btn-secondary" @click="step--"><ArrowLeft :size="18"/>Back</button><span v-else/><button v-if="step < 3" class="btn-primary" @click="step++">Continue<ArrowRight :size="18"/></button><button v-else class="btn-primary" :disabled="saving" @click="createLoan"><Check :size="18"/>{{ saving ? 'Creating...' : 'Confirm loan' }}</button></div></section></div></template>
